Review this embedded C function for an STM32 that processes incoming UART data in a command parser:

void parse_command(UART_HandleTypeDef *huart) {
  char buffer[2048];
  char response[2048];
  int len = 0;

  HAL_UART_Receive(huart, (uint8_t*)buffer, 2048, 1000);

  if (strncmp(buffer, "GET_SENSOR", 10) == 0) {
    float readings[256];
    for (int i = 0; i < 256; i++) {
      readings[i] = read_adc(i);
    }
    len = snprintf(response, 2048, "DATA:");
    for (int i = 0; i < 256; i++) {
      len += snprintf(response + len, 2048 - len, "%.2f,", readings[i]);
    }
    HAL_UART_Transmit(huart, (uint8_t*)response, len, 5000);
  }
}

This function is called from the main loop. The MCU has 20KB of SRAM. What issues do you see?

Review this interrupt-driven GPIO toggling code for STM32:

uint8_t sensor_ready = 0;
uint32_t sensor_value = 0;

void EXTI0_IRQHandler(void) {
  if (__HAL_GPIO_EXTI_GET_IT(GPIO_PIN_0) != RESET) {
    __HAL_GPIO_EXTI_CLEAR_IT(GPIO_PIN_0);
    sensor_value = read_sensor_register();
    sensor_ready = 1;
  }
}

int main(void) {
  HAL_Init();
  SystemClock_Config();
  MX_GPIO_Init();

  while (1) {
    if (sensor_ready) {
      process_data(sensor_value);
      sensor_ready = 0;
    }
    HAL_Delay(10);
  }
}

The system works in debug mode but in release mode (with optimizations -O2), sensor_ready never seems to become 1 in the main loop. What is wrong?

